import json, re, ast
from fractions import Fraction

def eval_expr(expr):
    # lenient AST eval supporting unary +/-, ints, floats? only ints here
    def ev(n):
        if isinstance(n, ast.Expression): return ev(n.body)
        if isinstance(n, ast.Constant) and type(n.value) is int: return Fraction(n.value)
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, ast.USub): return -ev(n.operand)
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, ast.UAdd): return ev(n.operand)
        if isinstance(n, ast.BinOp):
            a,b = ev(n.left), ev(n.right)
            if isinstance(n.op, ast.Add): return a+b
            if isinstance(n.op, ast.Sub): return a-b
            if isinstance(n.op, ast.Mult): return a*b
            if isinstance(n.op, ast.Div): return a/b
        raise ValueError
    return ev(ast.parse(expr, mode='eval'))

ANN = re.compile(r'<answer>(.*?)</answer>', re.DOTALL)
for step in [0,15,30,45]:
    rows=[json.loads(l) for l in open(f'results/grpo_countdown/val_generations/{step}.jsonl')]
    n=len(rows); has_ann=0; score=0; lenient=0; parse_ok=0
    for r in rows:
        gt=json.loads(r['gts']); t=gt['target']; nums=sorted(gt['numbers'])
        ms=ANN.findall(r['output'])
        if ms: has_ann+=1
        score += r['score']
        e=ms[-1].strip() if ms else ''
        if not e: continue
        e=e.replace('\\times','*').replace('\\div','/').replace('×','*').replace('÷','/')
        if '=' in e: e=e.split('=')[0].strip()
        if not re.fullmatch(r'[0-9+\-*/()\s]+', e): continue
        try:
            used=[]
            # replicate reward used-number collection
            def collect(n):
                if isinstance(n, ast.Expression): collect(n.body)
                elif isinstance(n, ast.Constant) and type(n.value) is int: used.append(n.value)
                elif isinstance(n, ast.BinOp): collect(n.left); collect(n.right)
            collect(ast.parse(e, mode='eval'))
            v=eval_expr(e)
            parse_ok+=1
            if sorted(used)==nums and v==t:
                lenient+=1
        except Exception:
            pass
    print(step, 'n',n,'has_tag',has_ann,'score_sum',score,'reward_recomputed_val',lenient,'parsed',parse_ok)
