import pyarrow.parquet as pq
from fractions import Fraction
from functools import lru_cache
import itertools, collections

t = pq.read_table('/user/user1/autorlbench-runs/20261122030352-75495-65c7/workspace/raw/countdown/data/train-00000-of-00001.parquet')
targets=t['target'].to_pylist(); nums=t['nums'].to_pylist()

def solvable(ns, target):
    target=Fraction(target)
    # DP over index subsets -> set of values
    n=len(ns)
    vals=[None]*(1<<n)
    for i in range(n):
        vals[1<<i]={Fraction(ns[i])}
    for mask in range(1,1<<n):
        if mask & (mask-1)==0: continue
        cur=set()
        sub=(mask-1)&mask
        while sub:
            other=mask^sub
            if other:
                for a in vals[sub]:
                    for b in vals[other]:
                        cur.add(a+b); cur.add(a-b); cur.add(b-a); cur.add(a*b)
                        if b!=0: cur.add(a/b)
                        if a!=0: cur.add(b/a)
            sub=(sub-1)&mask
        vals[mask]=cur
    return target in vals[(1<<n)-1]

import random
random.seed(1)
test_idx=list(range(len(targets)-1024,len(targets)))
tr_idx=random.sample(range(32768), 300)
for name,idxs in [('test',test_idx),('train_sample',tr_idx)]:
    bad=0
    for i in idxs:
        if not solvable(nums[i], targets[i]):
            bad+=1
            if bad<=5: print('unsolvable',name,i,targets[i],nums[i])
    print(name,'unsolvable',bad,'/',len(idxs))
