import json, re, ast
from fractions import Fraction
ANN=re.compile(r'<answer>(.*?)</answer>', re.DOTALL)
def norm(e):
    e=e.strip()
    e=e.replace('\\times','*').replace('\\div','/').replace('×','*').replace('÷','/')
    e=e.replace('−','-').replace('–','-').replace('\\cdot','*')
    e=re.sub(r'\\frac\{([^{}]*)\}\{([^{}]*)\}', r'((\1)/(\2))', e)
    e=re.sub(r'\\\(|\\\)|\\\[|\\\]','',e)
    e=e.replace(',','')
    return e
def ev(n):
    if isinstance(n, ast.Expression): return ev(n.body)
    if isinstance(n, ast.Constant) and type(n.value) in (int,float): return Fraction(str(n.value))
    if isinstance(n, ast.UnaryOp) and isinstance(n.op, ast.USub): return -ev(n.operand)
    if isinstance(n, ast.UnaryOp) and isinstance(n.op, ast.UAdd): return ev(n.operand)
    if isinstance(n, ast.BinOp):
        a,b=ev(n.left),ev(n.right)
        if isinstance(n.op,ast.Add): return a+b
        if isinstance(n.op,ast.Sub): return a-b
        if isinstance(n.op,ast.Mult): return a*b
        if isinstance(n.op,ast.Div):
            if b==0: raise ZeroDivisionError
            return a/b
    raise ValueError
def collect(n,acc):
    if isinstance(n,ast.Expression): collect(n.body,acc)
    elif isinstance(n,ast.Constant) and type(n.value) is int: acc.append(n.value)
    elif isinstance(n,ast.UnaryOp): collect(n.operand,acc)
    elif isinstance(n,ast.BinOp): collect(n.left,acc); collect(n.right,acc)
def expr_ok(e, gt):
    e=norm(e)
    if '=' in e: e=e.split('=')[0].strip()
    if not e or len(e)>256: return False
    try:
        tree=ast.parse(e,mode='eval'); acc=[]; collect(tree,acc); v=ev(tree)
    except Exception: return False
    return sorted(acc)==sorted(gt['numbers']) and v==Fraction(gt['target'])
def val_ok(out, gt):
    ms=ANN.findall(out)
    if not ms:
        return False
    return any(expr_ok(m,gt) for m in ms)
for step in [0,15,30,45]:
    rows=[json.loads(l) for l in open(f'results/grpo_countdown/val_generations/{step}.jsonl')]
    stricter=sum(r['score'] for r in rows)
    permissive=sum(1 for r in rows if val_ok(r['output'], json.loads(r['gts'])))
    print(step,'official',stricter,'permissive',permissive, 'delta', permissive-stricter)
    # print examples of permissive-only
    n=0
    for r in rows:
        if r['score']==0 and val_ok(r['output'], json.loads(r['gts'])):
            print('  extra:',r['gts'], repr(ANN.findall(r['output'])[-1][:160]))
            n+=1
            if n>=5: break
