import json, re, ast, collections
from fractions import Fraction
ANN=re.compile(r'<answer>(.*?)</answer>', re.DOTALL)
def parse(e):
    e=e.strip()
    if '=' in e: e=e.split('=')[0].strip()
    e=e.replace('\\times','*').replace('\\div','/')
    if not re.fullmatch(r'[0-9+\-*/()\s]+',e): return None
    try: tree=ast.parse(e,mode='eval')
    except Exception: return None
    acc=[]
    def coll(n):
        if isinstance(n,ast.Expression): coll(n.body)
        elif isinstance(n,ast.Constant) and type(n.value) is int: acc.append(n.value)
        elif isinstance(n,ast.BinOp): coll(n.left); coll(n.right)
    coll(tree); return acc
def ev(e):
    e=e.strip()
    if '=' in e: e=e.split('=')[0].strip()
    e=e.replace('\\times','*').replace('\\div','/')
    try: tree=ast.parse(e,mode='eval')
    except Exception: return None
    def f(n):
        if isinstance(n,ast.Expression): return f(n.body)
        if isinstance(n,ast.Constant) and type(n.value) is int: return Fraction(n.value)
        if isinstance(n,ast.BinOp):
            a,b=f(n.left),f(n.right)
            if isinstance(n.op,ast.Add): return a+b
            if isinstance(n.op,ast.Sub): return a-b
            if isinstance(n.op,ast.Mult): return a*b
            if isinstance(n.op,ast.Div): return a/b
        raise ValueError
    try: return f(tree)
    except Exception: return None
for step in [0,45]:
    rows=[json.loads(l) for l in open(f'results/grpo_countdown/val_generations/{step}.jsonl')]
    c=collections.Counter(); extra=collections.Counter()
    for r in rows:
        gt=json.loads(r['gts']); ms=ANN.findall(r['output'])
        if not ms: continue
        acc=parse(ms[-1])
        if acc is None: continue
        want=sorted(gt['numbers']); got=sorted(acc)
        if got!=want:
            if len(got)>len(want) and all(x in got for x in want) if False else False: pass
            # multiset compare via Counter
            cw=collections.Counter(want); cg=collections.Counter(got)
            if all(cg[k]>=cw[k] for k in cw) and sum(cg.values())>sum(cw.values()):
                c['superset']+=1
                for k,v in (cg-cw).items(): extra[k]+=v
            elif all(cw[k]>=cg[k] for k in cg) and sum(cg.values())<sum(cw.values()):
                c['subset']+=1
            else:
                c['different']+=1
            if gt['target'] in got: c['uses_target_value']+=1
            if 1 in (cg-cw): c['extra_1']+=1
            if 2 in (cg-cw): c['extra_2']+=1
    print(step, dict(c))
    print('  top extra numbers', extra.most_common(8))
