import json, re, ast
from fractions import Fraction
ANN=re.compile(r'<answer>(.*?)</answer>', re.DOTALL)
def ok(e,gt):
    e=e.strip().replace('\\times','*').replace('\\div','/').replace('×','*').replace('÷','/')
    if '=' in e: e=e.split('=')[0].strip()
    e=re.sub(r'\\frac\{([^{}]*)\}\{([^{}]*)\}', r'((\1)/(\2))', e)
    e=re.sub(r'\\\(|\\\)|\\\[|\\\]','',e).replace(',','')
    if not e or not re.fullmatch(r'[0-9+\-*/()\s]+',e): return False
    try: tree=ast.parse(e,mode='eval')
    except Exception: return False
    def ev(n):
        if isinstance(n,ast.Expression): return ev(n.body)
        if isinstance(n,ast.Constant) and type(n.value) is int: return Fraction(n.value)
        if isinstance(n,ast.UnaryOp) and isinstance(n.op,ast.USub): return -ev(n.operand)
        if isinstance(n,ast.BinOp):
            a,b=ev(n.left),ev(n.right)
            if isinstance(n.op,ast.Add): return a+b
            if isinstance(n.op,ast.Sub): return a-b
            if isinstance(n.op,ast.Mult): return a*b
            if isinstance(n.op,ast.Div):
                if b==0: raise ZeroDivisionError
                return a/b
        raise ValueError
    def coll(n,acc):
        if isinstance(n,ast.Expression): coll(n.body,acc)
        elif isinstance(n,ast.Constant) and type(n.value) is int: acc.append(n.value)
        elif isinstance(n,ast.UnaryOp): coll(n.operand,acc)
        elif isinstance(n,ast.BinOp): coll(n.left,acc); coll(n.right,acc)
    try:
        acc=[]; coll(tree,acc); v=ev(tree)
