from fractions import Fraction
import random
random.seed(1)

def solvable(nums, target, ops_ok, max_terms=None):
    # DP over subsets returning set of reachable values
    from functools import lru_cache
    n=len(nums)
    vals={}
    for i,v in enumerate(nums):
        vals[frozenset([i])]={Fraction(v)}
    for size in range(2,n+1):
        for comb in itertools.combinations(range(n),size):
            s=frozenset(comb); out=set()
            # split
            s_list=list(comb)
            for r in range(1,len(s_list)):
                for left in itertools.combinations(s_list,r):
                    right=[x for x in s_list if x not in left]
                    L=vals[frozenset(left)]; R=vals[frozenset(right)]
                    for a in L:
                        for b in R:
                            out.add(a+b)
                            if ops_ok>=2: out.add(a-b); out.add(b-a)
                            out.add(a*b)
                            if ops_ok>=3 and b!=0: out.add(a/b)
                            if ops_ok>=3 and a!=0: out.add(b/a)
